		if (plan instanceof JoinPlan join) {
			return contains(join.left, seen) || contains(join.right, seen);
		}
		if (plan instanceof FilterPlan filter) {
			return contains(filter.arg, seen);
		}
		if (plan instanceof ExtensionPlan extension) {
			return contains(extension.arg, seen);
		}
		if (plan instanceof EntryBindingCompatibilityPlan entry) {
			return contains(entry.arg, seen);
		}
		if (plan instanceof RowDistinctPlan distinct) {
			return contains(distinct.arg, seen);
		}
		if (plan instanceof UnionPlan union) {
			return contains(union.left, seen) || contains(union.right, seen);
		}
		if (plan instanceof OrderedUnionPlan union) {
			return contains(union.left, seen) || contains(union.right, seen);
		}
		if (plan instanceof LeftJoinPlan optional) {
			return contains(optional.left, seen) || contains(optional.right, seen);
		}
		if (plan instanceof MinusPlan minus) {
			return contains(minus.left, seen) || contains(minus.right, seen);
		}
		if (plan instanceof DrainGuardPlan guard) {
			return contains(guard.delegate, seen) || contains(guard.drained, seen);
		}
		if (plan instanceof LateralPlan lateral) {
			return contains(lateral.left, seen) || contains(lateral.right, seen);
		}
		return false;
