	static Selection select(SlotPlan plan, RowState row, Request request) {
		boolean optimized = request != null && request.matches(plan, row) && !row.encounterOrderRequired;
		Resolution resolution = new Resolution();
		SlotPlan selected = resolve(plan, optimized, resolution);
		if (resolution.conflictingDemands) {
			// A shared lexical boundary cannot carry both permissions. Discard the unopened provisional graph,
			// then resolve the entire input lexically before exposing a graph to recognizers or consumers.
			resolution = new Resolution();
			selected = resolve(plan, false, resolution);
		}
		return new Selection(plan, selected, row, Collections.unmodifiableMap(resolution.boundaries));
	}

	static final class Request {
		private final SlotPlan plan;
		private final NativeLmdbQuerySource source;
		private final NativeSlotLayout layout;

		private Request(SlotPlan plan, NativeLmdbQuerySource source, NativeSlotLayout layout) {
			this.plan = plan;
			this.source = source;
			this.layout = layout;
		}

		private boolean matches(SlotPlan candidate, RowState row) {
			if (candidate != plan || row.layout != layout) {
				return false;
			}
			if (!(source instanceof SyntheticValueSource compiled)
					|| !(row.source instanceof SyntheticValueSource active)) {
				return row.source == source;
			}
			return active.delegate == compiled.delegate && active.catalog == compiled.catalog
					&& active.queryExecutionPolicy == compiled.queryExecutionPolicy
					&& active.executionContext() != null && !active.executionContext().isClosed();
		}
	}

	/** Invocation-local owned input, selected before any physical recognizer or child open. */
	static final class Selection {
		final SlotPlan original;
		final SlotPlan plan;
		private final NativeLmdbQuerySource source;
		private final Object idSpace;
		private final NativeSlotLayout layout;
		private final Object base;
		private final long lexicalInputMask;
		private final int lexicalScopeDepth;
		private final boolean optimized;
		private final Map<SlotPlan, Boolean> boundaries;

		private Selection(SlotPlan original, SlotPlan plan, RowState row,
				Map<SlotPlan, Boolean> boundaries) {
			this.original = original;
			this.plan = plan;
			this.source = row.source;
			this.idSpace = row.source.idSpace();
			this.layout = row.layout;
			this.base = row.base;
			this.lexicalInputMask = row.lexicalInputMask;
			this.lexicalScopeDepth = row.lexicalScopeDepth;
			this.optimized = boundaries.containsValue(Boolean.TRUE);
			this.boundaries = boundaries;
		}

		boolean matches(RowState row) {
			return row.source == source && row.source.idSpace() == idSpace && row.layout == layout
					&& row.base == base && row.lexicalInputMask == lexicalInputMask
					&& row.lexicalScopeDepth == lexicalScopeDepth
					&& (!(source instanceof SyntheticValueSource values)
							|| values.executionContext() != null && !values.executionContext().isClosed());
		}

		private Selection(Selection original, NativeFilterLease filters) {
			this.original = filters.borrow(original.original);
			this.plan = filters.borrow(original.plan);
			this.source = original.source;
			this.idSpace = original.idSpace;
			this.layout = original.layout;
			this.base = original.base;
			this.lexicalInputMask = original.lexicalInputMask;
			this.lexicalScopeDepth = original.lexicalScopeDepth;
			this.optimized = original.optimized;
			Map<SlotPlan, Boolean> copied = new IdentityHashMap<>();
			for (Map.Entry<SlotPlan, Boolean> boundary : original.boundaries.entrySet()) {
				copied.put(filters.borrow(boundary.getKey()), boundary.getValue());
			}
			this.boundaries = Collections.unmodifiableMap(copied);
		}

		Selection borrow(NativeFilterLease filters) {
			return new Selection(this, filters);
		}

		boolean requiresLexical(RowState row) {
			return optimized && row.encounterOrderRequired;
		}

		boolean observes(SlotPlan graph) {
			return !boundaries.isEmpty() && (graph == plan || boundaries.containsKey(graph));
		}

		void opened(RowState row, SlotPlan graph) {
			if (matches(row) && observes(graph)) {
				boolean moved = graph == plan ? optimized : Boolean.TRUE.equals(boundaries.get(graph));
				LmdbNativeExplain.addRuntimeMetric(row.telemetryTarget, moved ? OPTIMIZED_OPEN : LEXICAL_OPEN, 1L);
			}
		}

		void validate(RowState row, SlotPlan graph) {
			if (!matches(row) || graph != plan && !boundaries.containsKey(graph)) {
				throw new IllegalStateException("interior input outlived its owned evaluation frame");
			}
			if (row.encounterOrderRequired
					&& (graph == plan ? optimized : Boolean.TRUE.equals(boundaries.get(graph)))) {
				throw new IllegalStateException("ordered consumer must select the lexical input before recognition");
			}
		}

		RowCursor observed(RowState row, SlotPlan graph, RowCursor cursor) {
			try {
				opened(row, graph);
				return cursor;
			} catch (RuntimeException | Error failure) {
				try {
					cursor.close();
				} catch (RuntimeException | Error cleanup) {
					if (cleanup != failure) {
						failure.addSuppressed(cleanup);
					}
				}
				throw failure;
			}
		}

		/** Actual successful stream open, distinct from planned movement or physical packed-region publication. */
		RowCursor open(RowState row, SlotPlan graph) throws IOException {
			validate(row, graph);
			return observed(row, graph, graph.open(row));
		}
	}

	private static final class Carrier implements SlotPlan {
		private final SlotPlan lexical;
		private final SlotPlan core;
		private final Spine boundaries;
		private final boolean nativePrefix;
		private final int nativeOperandCount;

		private Carrier(SlotPlan lexical, SlotPlan core, Spine boundaries, boolean nativePrefix,
				int nativeOperandCount) {
			this.lexical = lexical;
			this.core = core;
			this.boundaries = boundaries;
			this.nativePrefix = nativePrefix;
			this.nativeOperandCount = nativeOperandCount;
		}

		private SlotPlan optimized() {
			List<SlotPlan> leaves = new ArrayList<>();
			boundaries.collect(leaves);
			SlotPlan result = core;
			if (nativePrefix) {
				for (int i = leaves.size() - 1; i >= 0; i--) {
					result = SlotPlan.join(leaves.get(i), result);
				}
			} else {
				for (SlotPlan boundary : leaves) {
					result = SlotPlan.join(result, boundary);
				}
			}
			return result;
		}

		@Override
		public RowCursor open(RowState row) throws IOException {
			return select(this, row, null).open(row, lexical);
		}

		@Override
		public long producedMask() {
			return lexical.producedMask();
		}

		@Override
		public double estimate(RowState row) {
			return lexical.estimate(row);
		}

		@Override
		public LmdbNativeWork estimateWork(RowState row, long boundMask) {
			return lexical.estimateWork(row, boundMask);
		}

		@Override
		public double estimateRows(RowState row, long boundMask) {
			return lexical.estimateRows(row, boundMask);
		}
	}

	/** Persistent concatenation tree: append and merge retain existing plans without copying their alternatives. */
	private static final class Spine {
		private final SlotPlan boundary;
		private final Spine left;
		private final Spine right;

		private Spine(SlotPlan boundary, Spine left, Spine right) {
			this.boundary = boundary;
			this.left = left;
			this.right = right;
		}

		static Spine leaf(SlotPlan boundary) {
			return new Spine(boundary, null, null);
		}

		static Spine concat(Spine left, Spine right) {
			return left == null ? right : right == null ? left : new Spine(null, left, right);
		}

		void collect(List<SlotPlan> result) {
			ArrayDeque<Spine> pending = new ArrayDeque<>();
			pending.push(this);
			while (!pending.isEmpty()) {
				Spine node = pending.pop();
				if (node.boundary != null) {
					result.add(node.boundary);
				} else {
					pending.push(node.right);
					pending.push(node.left);
				}
			}
		}

		Spine borrow(NativeFilterLease filters) {
			List<SlotPlan> leaves = new ArrayList<>();
			collect(leaves);
			Spine result = null;
			for (SlotPlan leaf : leaves) {
				result = concat(result, leaf(filters.borrow(leaf)));
			}
			return result;
		}
	}
